import { writeFileSync } from 'node:fs';
import { afterAll, afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { initCodeExamples } from './code-example-client';

// Disposable diagnosis on bf8, not a native-browser result. The actual current
// controller, WC Tabs and WC Tree run unchanged. Only idle callback delivery is
// controlled; .click()/focus are synthetic HappyDOM host actions.
const idle = new Map<number, IdleRequestCallback>();
const observations: unknown[] = [];
let sequence = 0;
let caseName = '';
let errors: string[] = [];
let root: HTMLElement;
const flush = async () => { for (let n = 0; n < 4; n++) await Promise.resolve(); };
const panel = (host: string) => root.querySelector<HTMLElement>(`[data-code-host-panel][data-code-host="${host}"]`)!;
const fileList = (host: string) => panel(host).querySelector<HTMLElement>('[data-code-file-tabs]')!;
const trees = (host: string) => panel(host).querySelectorAll('[data-code-example-tree][role="tree"]').length;
function sample(stage: string) {
  const facts = {
    caseName, stage, pendingIdle: idle.size,
    hostTabs: root.querySelectorAll('[data-code-example-tabs-projection]').length,
    activeElement: document.activeElement?.id || document.activeElement?.localName,
    hosts: ['wc', 'react'].map((host) => ({
      host, hidden: panel(host).hidden, trees: trees(host), nativeFileListHidden: fileList(host).hidden,
      selectedFile: fileList(host).querySelector('[aria-selected="true"]')?.textContent,
      visibleSource: [...panel(host).querySelectorAll<HTMLElement>('[data-code-file-panel]')].filter(p => !p.hidden).map(p => p.textContent),
    })),
    errors: [...errors],
  };
  observations.push(facts);
  return facts;
}
async function deliverIdle() {
  const next = idle.entries().next().value;
  if (!next) throw new Error('Expected a scheduled real controller callback');
  const [id, callback] = next;
  idle.delete(id);
  callback({ didTimeout: false, timeRemaining: () => 40 });
  await flush();
}
function fixture() {
  const names = { wc: ['src/main.ts', 'index.html'], react: ['src/App.tsx', 'src/theme.css'] };
  document.body.innerHTML = `<section data-code-example data-initial-host="react">
    <div data-code-toolbar><nav data-code-host-tabs aria-label="Host">
      <a id="host-wc" data-code-host-tab data-code-host="wc" data-code-host-name="Web Components" aria-controls="panel-wc">Web Components</a>
      <a id="host-react" data-code-host-tab data-code-host="react" data-code-host-name="React" aria-controls="panel-react">React</a>
    </nav></div>
    ${(['wc', 'react'] as const).map(host => `<section id="panel-${host}" data-code-host-panel data-code-host="${host}" ${host === 'react' ? '' : 'hidden'}>
      <section data-code-file-browser><aside><nav data-code-file-tabs aria-label="Files">
        ${names[host].map((name, i) => `<a id="file-${host}-${i}" data-code-file-tab data-code-file-index="${i}" data-code-file-path="${name}" aria-controls="source-${host}-${i}">${name}</a>`).join('')}
      </nav></aside><div data-code-file-source>
        ${names[host].map((name, i) => `<figure id="source-${host}-${i}" data-code-file-panel data-code-file-index="${i}" ${i ? 'hidden' : ''}><pre>${host}:${name}</pre></figure>`).join('')}
      </div></section>
    </section>`).join('')}
  </section>`;
  return document.querySelector<HTMLElement>('[data-code-example]')!;
}
async function admitInitialReact() {
  initCodeExamples(root);
  await deliverIdle();
  await deliverIdle();
  expect(trees('react')).toBe(1);
  expect(trees('wc')).toBe(0);
  expect(idle.size).toBe(0);
}
async function selectHost(host: 'wc' | 'react') {
  const index = host === 'wc' ? 0 : 1;
  const trigger = root.querySelector<HTMLElement>(`[data-code-example-projected-tab="${index}"]`)!;
  trigger.click();
  await flush();
  expect(panel(host).hidden).toBe(false);
}
beforeEach(({ task }) => {
  caseName = task.name;
  errors = [];
  idle.clear();
  localStorage.clear();
  vi.stubGlobal('requestIdleCallback', (callback: IdleRequestCallback) => {
    const id = ++sequence;
    idle.set(id, callback);
    return id;
  });
  vi.stubGlobal('cancelIdleCallback', (id: number) => idle.delete(id));
  vi.spyOn(console, 'error').mockImplementation((...args) => errors.push(args.map(value => value instanceof Error ? `${value.name}: ${value.message}` : String(value)).join(' ')));
  root = fixture();
});
afterEach(() => {
  document.dispatchEvent(new Event('astro:before-swap'));
  document.body.replaceChildren();
  vi.restoreAllMocks();
  vi.unstubAllGlobals();
  idle.clear();
});
afterAll(() => writeFileSync('/workspace/scratch/46c8fad17f2b/codeexample-recovery-20261117/scheduling-observations.json', JSON.stringify({ native: false, injected: ['Idle callback delivery', 'Synthetic HappyDOM click/focus', 'Invalid duplicate path in explicit error-control case only'], actual: ['Current code-example-client', 'Current enhanceCodeExampleTabs', 'Current enhanceCodeExampleTree', 'Real AdaptToWebComponent'], observations }, null, 2) + '\n'));

describe('bounded real CodeExample scheduling observations', () => {
  it('admits native controls, host Tabs and only the current file Tree in separate turns', async () => {
    const sources = [...root.querySelectorAll('pre')];
    initCodeExamples(root);
    sample('initialized-before-idle');
    expect(trees('react')).toBe(0);
    expect(fileList('react').hidden).toBe(false);
    root.querySelector<HTMLElement>('#file-react-1')!.click();
    expect(root.querySelector<HTMLElement>('#source-react-1')!.hidden).toBe(false);
    await deliverIdle();
    sample('first-idle-host-tabs-only');
    expect(root.querySelectorAll('[data-code-example-tabs-projection]')).toHaveLength(1);
    expect(trees('react')).toBe(0);
    await deliverIdle();
    sample('second-idle-current-react-tree');
    expect(trees('react')).toBe(1);
    expect(trees('wc')).toBe(0);
    expect([...root.querySelectorAll('pre')]).toEqual(sources);
    expect(errors).toEqual([]);
  });

  it('keeps newly selected WC source immediately usable while its real Tree awaits idle', async () => {
    await admitInitialReact();
    const sources = [...root.querySelectorAll('pre')];
    sample('react-current-before-switch');
    await selectHost('wc');
    sample('wc-selected-before-idle');
    expect(trees('wc')).toBe(0);
    expect(fileList('wc').hidden).toBe(false);
    expect(idle.size).toBe(1);
    root.querySelector<HTMLElement>('#file-wc-1')!.click();
    expect(root.querySelector<HTMLElement>('#source-wc-1')!.hidden).toBe(false);
    await deliverIdle();
    sample('wc-after-its-next-idle');
    expect(trees('wc')).toBe(1);
    expect(fileList('wc').hidden).toBe(true);
    expect(panel('wc').querySelector('[data-code-tree-path="index.html"]')?.getAttribute('aria-selected')).toBe('true');
    expect([...root.querySelectorAll('pre')]).toEqual(sources);
    expect(errors).toEqual([]);
  });

  it('distinguishes a focused native-file fallback from pending idle or a thrown Tree error', async () => {
    await admitInitialReact();
    await selectHost('wc');
    const focused = root.querySelector<HTMLElement>('#file-wc-0')!;
    focused.focus();
    await deliverIdle();
    sample('focused-native-file-retained');
    expect(document.activeElement).toBe(focused);
    expect(trees('wc')).toBe(0);
    expect(fileList('wc').hidden).toBe(false);
    expect(idle.size).toBe(0);
    expect(errors).toEqual([]);
    focused.blur();
    await selectHost('react');
    await selectHost('wc');
    sample('focus-fallback-not-retried-after-revisit');
    expect(idle.size).toBe(0);
    expect(trees('wc')).toBe(0);
  });

  it('records the real rejection for an explicitly injected duplicate file path', async () => {
    await admitInitialReact();
    root.querySelector<HTMLElement>('#file-wc-1')!.dataset.codeFilePath = 'src/main.ts';
    await selectHost('wc');
    await deliverIdle();
    sample('invalid-path-error-retains-native-files');
    expect(trees('wc')).toBe(0);
    expect(fileList('wc').hidden).toBe(false);
    expect(idle.size).toBe(0);
    expect(errors).toHaveLength(1);
    expect(errors[0]).toContain('[CodeExample] Real Tree unavailable; retaining native file controls.');
    expect(errors[0]).toMatch(/duplicate|unique/i);
  });
});

